import json,numpy as np
from pathlib import Path
b=Path(r'[workspace]/Astra\made\final-night-2026-11-05\fresh18\batch02');raw=json.loads((b/'159860053/lead-timing.json').read_text());new=json.loads((b/'lead-s106-timing.json').read_text());t=np.array([e['center_btjd'] for e in raw+new]);k=np.array([0 if e['kind']=='deep' else 1 for e in raw+new]);epochs=[raw[0]['center_btjd'],raw[1]['center_btjd']];cycles=np.rint((t-np.array(epochs)[k])/23.964).astype(int);err=np.array([max(e.get('center_formal_error_d',e.get('formal_center_error_d',0)),e.get('cadence_d',.002315)/2) for e in raw+new]);X=np.stack([k==0,k==1,cycles],axis=1).astype(float);W=1/err**2;cov=np.linalg.inv(X.T@(W[:,None]*X));v=cov@(X.T@(W*t));res=t-X@v;out=dict(period_d=float(v[2]),deep_epoch_btjd=float(v[0]),shallow_epoch_btjd=float(v[1]),event_btjd=t.tolist(),kinds=k.tolist(),cycles=cycles.tolist(),residuals_d=res.tolist(),formal_period_error_d=float(np.sqrt(cov[2,2])),scatter_inflated_period_error_d=float(np.sqrt(cov[2,2])*max(1,np.sqrt(np.sum((res/err)**2)/(len(t)-3)))),note='Separate deep/shallow epochs and common period. Original QLP raw SAP plus S106 custom TESScut; cadence-floor local fit errors. Scatter inflation is diagnostic, not calibrated total coverage.');(b/'lead-y010-two-kind-refit.json').write_text(json.dumps(out,indent=2));print(out)
